from __future__ import annotations


HTML = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>mdoc 手册反馈修订</title><style>
.translation-markdown p>img:only-child{display:inline;margin:0;vertical-align:middle}.translation-markdown p.standalone-image>img{display:block;margin:.8em auto}
.translation-selection>b{display:block;margin-bottom:6px;color:#8a5200}.translation-selection>div{font-weight:600}
.layout.translation-mode{grid-template-columns:minmax(0,1fr)!important}.layout.translation-mode>#files,.layout.translation-mode>#matches,.layout.translation-mode>.splitter{display:none}.layout.translation-mode>#workbench{grid-column:1/-1}
.layout.image-mode{grid-template-columns:330px 6px minmax(680px,1fr)}.layout.image-mode>#matches,.layout.image-mode>#matches+.splitter{display:none}
.image-workspace.source-closed{grid-template-rows:auto minmax(320px,1fr) 0 0}
.image-workspace{height:100%;display:grid;grid-template-rows:auto minmax(320px,1fr) 6px var(--image-source-height,220px);overflow:hidden}.image-tools{display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:8px;border-bottom:1px solid #d9dfdc;background:#f8faf9}.image-tools .meta{margin-left:auto}.image-body{min-width:860px;display:grid;grid-template-columns:var(--image-list-width,240px) 6px minmax(320px,var(--image-original-width,1fr)) 6px minmax(320px,1fr);overflow:auto}.image-splitter{background:#e3e8e5;cursor:col-resize}.image-splitter:hover,.image-splitter.dragging{background:#9bb4a8}.image-entry{display:block;width:100%;padding:10px;text-align:left;border:0;border-bottom:1px solid #e7ebe9;background:#fff}.image-entry.active,.image-entry:hover{background:#eef5f1}.image-entry .status{display:block;margin-top:4px;color:#687078;font-size:12px}.image-entry .candidate{color:#8a5200}.image-entry .saved{color:#137333}.image-format-warning{color:#8a5200!important}.image-view{min-width:0;display:grid;grid-template-rows:auto minmax(0,1fr);border-left:1px solid #edf0ee}.image-view-head{padding:8px 10px;border-bottom:1px solid #e1e5e3;background:#fff}.image-canvas{position:relative;overflow:hidden;background:#30343a;touch-action:none}.image-canvas img{position:absolute;left:50%;top:50%;max-width:none;transform-origin:center center;user-select:none;pointer-events:none}.image-placeholder{height:100%;display:grid;place-items:center;padding:24px;color:#d5d9d7;text-align:center}.image-source-splitter{cursor:row-resize;background:#e3e8e5}.image-source-splitter:hover,.image-source-splitter.dragging{background:#9bb4a8}.image-source{min-height:160px;overflow:auto;border-top:1px solid #d9dfdc;background:#fff}.image-source.hidden+.image-source-splitter{display:none}.image-source-toolbar{position:sticky;top:0;z-index:2;display:flex;gap:6px;align-items:center;padding:6px 8px;border-bottom:1px solid #ddd;background:#fff}.image-source-code{margin:0;padding:10px 0;font:13px/1.55 Consolas,monospace;white-space:pre-wrap}.image-source-line{display:block;padding:0 12px}.image-source-line.ref{background:#fff2a8}.image-source-line.current{background:#ffd666;box-shadow:inset 4px 0 #b7791f}.image-file-input{display:none}
 .search textarea{height:30px!important}.notice span{white-space:pre-wrap}
.translation-progress{display:grid;gap:6px;padding:9px 10px;color:#285b45;background:#edf7f1;border:1px solid #b8dbc8}.translation-progress-track{height:5px;overflow:hidden;background:#d2e8dc}.translation-progress-track::after{content:"";display:block;width:36%;height:100%;background:#2f7d59;animation:translation-progress 1.1s ease-in-out infinite}@keyframes translation-progress{0%{transform:translateX(-110%)}100%{transform:translateX(310%)}}.translation-context-flow{display:grid;gap:8px;margin-top:10px}.translation-context-block{padding:10px 12px;border-left:4px solid transparent}.translation-context-before{background:#f5f7fa;border-color:#aab4c0}.translation-context-current{background:#fff8d8;border-color:#d5a400}.translation-context-after{background:#f3f8f5;border-color:#93b5a3}.translation-context-label{margin-bottom:6px;color:#59636e;font-size:12px;font-weight:650}.translation-markdown{font:15px/1.6 "Segoe UI","Microsoft YaHei",sans-serif}.translation-markdown>:first-child{margin-top:0}.translation-markdown>:last-child{margin-bottom:0}.translation-markdown h1,.translation-markdown h2,.translation-markdown h3,.translation-markdown h4,.translation-markdown h5,.translation-markdown h6{margin:1em 0 .45em;line-height:1.3}.translation-markdown p{margin:.65em 0}.translation-markdown blockquote{margin:.8em 0;padding:.5em .9em;color:#57606a;background:rgba(255,255,255,.55);border-left:4px solid #8c959f}.translation-markdown ul,.translation-markdown ol{margin:.65em 0;padding-left:2em}.translation-markdown img{max-width:100%;height:auto}.translation-markdown div[align=center]>img,.translation-markdown div[align="center"]>img{display:block;margin:.8em auto}.translation-markdown p img{vertical-align:middle}.translation-markdown table{display:block;width:max-content;max-width:100%;overflow:auto;border-collapse:collapse;margin:.8em 0}.translation-markdown td,.translation-markdown th{padding:6px 10px;border:1px solid #cfd6d2}.translation-markdown th{background:rgba(255,255,255,.55)}.translation-markdown code{padding:.12em .3em;background:rgba(255,255,255,.65);font:85% Consolas,monospace}.translation-markdown pre{max-height:280px;overflow:auto;padding:12px;background:rgba(255,255,255,.65);white-space:pre-wrap}.translation-markdown pre code{padding:0;background:transparent}.translation-target details>pre{max-height:280px;overflow:auto;padding:9px;background:#f6f8fa;white-space:pre-wrap}
.settings-section:last-child .settings-grid>.settings-field:last-child button{width:100%;height:40px;padding:0 14px;border:1px solid #9ca8a2;border-radius:4px;background:#fff}.settings-section:last-child .settings-grid>.settings-field:last-child button:hover{background:#f1f4f2}body.resizing{cursor:col-resize;user-select:none}body.resizing iframe{pointer-events:none}.splitter:hover{background:#aebdb6}.file-toolbar{justify-content:space-between;box-shadow:0 1px 3px rgba(32,33,36,.08)}.file-toolbar>div{display:flex;align-items:center;gap:6px;white-space:nowrap}.file-toolbar .page-meta{margin-left:auto}.file-toolbar button{height:30px}.file-toolbar select{height:30px}.file-toolbar button:disabled{cursor:default;opacity:.45}.translation-head,.translation-save{position:sticky;z-index:5;display:flex;align-items:center;gap:8px;padding:10px;background:#f8faf9;border-bottom:1px solid #d9dfdc}.translation-head{top:0}.translation-save{bottom:0;border-top:1px solid #d9dfdc;border-bottom:0}.translation-save button{margin-left:auto}.translation-summary-bar,.translation-languages{display:flex;gap:6px;flex-wrap:wrap;padding:8px;border-bottom:1px solid #ddd}.translation-grid{display:grid;grid-template-columns:minmax(300px,.8fr) minmax(420px,1.2fr);gap:12px;padding:12px}.translation-source,.translation-target{min-width:0;padding:12px;border:1px solid #d9dfdc;border-radius:6px}.translation-path{overflow-wrap:anywhere;color:#687078;font-family:Consolas,monospace}.translation-selection,.translation-current{padding:10px;background:#fff8d8;border-left:4px solid #d5a400;white-space:pre-wrap}.translation-context-row{display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:8px}.translation-context-row pre,.translation-target details pre{max-height:280px;overflow:auto;padding:9px;background:#f6f8fa;white-space:pre-wrap}.translation-candidate{display:grid;gap:8px;margin-top:10px}.translation-candidate textarea{min-height:150px;resize:vertical}.translation-target-head,.translation-flags{display:flex;align-items:center;justify-content:space-between;gap:10px}.translation-ok{padding:7px;color:#137333;background:#e6f4ea}.translation-warning{padding:7px;color:#8a5200;background:#fef7e0}.translation-compare{display:grid;grid-template-columns:1fr 1fr;gap:10px}.translation-summary{padding:24px}@media(max-width:1300px){.translation-grid{grid-template-columns:1fr}.translation-context-row{grid-template-columns:1fr}.translation-compare{grid-template-columns:1fr}}
*{box-sizing:border-box}body{margin:0;color:#202124;font:14px/1.5 "Segoe UI","Microsoft YaHei",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}header{height:58px;display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:1px solid #ddd}header h1{margin:0;font-size:18px}header nav{margin-left:auto}.notice{display:none;margin:10px 14px;padding:10px 12px;border:1px solid}.notice.show{display:flex}.notice span{flex:1}.notice.success{color:#137333;background:#e6f4ea;border-color:#a8dab5}.notice.warning{color:#8a5200;background:#fef7e0;border-color:#f3d37a}.notice.error{color:#b3261e;background:#fce8e6;border-color:#efaaa3}.search{display:grid;grid-template-columns:190px 130px minmax(280px,1fr) auto auto;gap:8px;padding:10px 14px;border-bottom:1px solid #ddd}.search textarea{height:72px;resize:vertical}.query-meta{grid-column:3;color:#687078}.layout{height:calc(100vh - 162px);display:grid;grid-template-columns:330px 6px 360px 6px minmax(440px,1fr)}.pane{min-width:0;overflow:auto}.splitter{cursor:col-resize;background:#e7ebe9}.toolbar{position:sticky;top:0;z-index:3;display:flex;align-items:center;gap:6px;padding:8px;background:#fff;border-bottom:1px solid #ddd}.file,.match{width:100%;padding:10px;text-align:left;border:0;border-bottom:1px solid #eee;background:#fff;cursor:pointer}.file:hover,.match:hover,.active{background:#eef5f1}.context{margin-top:5px;color:#687078;font:12px/1.4 Consolas,monospace;white-space:pre-wrap}.empty{padding:24px;color:#687078}.editor-tabs{position:sticky;top:0;z-index:4;display:flex;gap:4px;padding:8px;background:#fff;border-bottom:1px solid #ddd}.editor-tabs button.active{color:#137333;background:#e6f4ea}.locale-tabs{display:flex;gap:4px;overflow:auto}.editor-box{height:calc(100% - 86px);min-height:360px}.editor-head{height:42px;display:flex;align-items:center;gap:8px;padding:6px 9px;border-bottom:1px solid #ddd}.editor-head .path{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.editor-head .state{margin-left:auto;color:#687078}#editor-surface{height:calc(100% - 42px)}.preview{width:100%;height:100%;border:0}.image-list{padding:8px;border-top:1px solid #ddd}.image{padding:7px;border-bottom:1px solid #eee}.hidden{display:none!important}.pager{display:flex;gap:6px;align-items:center;padding:8px}.settings-dialog{width:min(720px,calc(100vw - 32px));max-height:calc(100vh - 48px);padding:0;border:1px solid #b7c1bc;border-radius:8px;background:#fff;box-shadow:0 20px 64px rgba(25,38,32,.3)}.settings-dialog::backdrop{background:rgba(26,35,31,.46)}.settings-head{display:flex;align-items:flex-start;gap:16px;padding:18px 22px 16px;border-bottom:1px solid #dfe4e1;background:#f8faf9}.settings-head h2{margin:0;font-size:20px;font-weight:650}.settings-head p{margin:4px 0 0;color:#687078}.settings-head button{margin:-2px -4px 0 auto;width:36px;height:36px;border:0;border-radius:4px;background:transparent;color:#59615d;font-size:23px;line-height:1}.settings-head button:hover{background:#e8ecea}.settings-body{display:grid;gap:16px;padding:20px 22px;overflow:auto}.settings-section{padding:17px 18px 18px;border:1px solid #d9dfdc;border-radius:6px;background:#fff}.settings-section h3{margin:0 0 14px;font-size:15px}.settings-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px 18px}.settings-field{display:grid;gap:6px;min-width:0}.settings-field.wide{grid-column:1/-1}.settings-field span{font-weight:600;color:#303632}.settings-field small{min-height:20px;color:#687078}.settings-field input,.settings-field select{width:100%;height:40px;padding:7px 10px;border:1px solid #aeb8b3;border-radius:4px;background:#fff;outline:0}.settings-field input:focus,.settings-field select:focus{border-color:#286b4d;box-shadow:0 0 0 2px rgba(40,107,77,.14)}.settings-model-row{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:start}.settings-model-row button{height:40px;margin-top:27px;padding:0 14px;white-space:nowrap;border:1px solid #9ca8a2;border-radius:4px;background:#fff}.settings-model-row button:hover,.settings-actions button:hover{background:#f1f4f2}.settings-status{display:none;padding:10px 12px;border:1px solid;border-radius:4px}.settings-status.show{display:block}.settings-status.success{color:#137333;background:#e6f4ea;border-color:#a8dab5}.settings-status.warning{color:#8a5200;background:#fef7e0;border-color:#f3d37a}.settings-status.error{color:#b3261e;background:#fce8e6;border-color:#efaaa3}.settings-actions{display:flex;align-items:center;gap:9px;padding:14px 22px;border-top:1px solid #dfe4e1;background:#f8faf9}.settings-actions .danger{color:#b3261e;border-color:#d7aaa6}.settings-actions .primary{margin-left:auto;color:#fff;background:#286b4d;border-color:#286b4d}.settings-actions .primary:hover{background:#205d42}.settings-actions button{height:38px;min-width:88px;padding:0 14px;border:1px solid #9ca8a2;border-radius:4px;background:#fff}.settings-actions #provider-cancel{margin-left:auto}.settings-actions .primary{margin-left:0}@media(max-width:1000px){.search{grid-template-columns:1fr 1fr}.search textarea,.query-meta{grid-column:1/-1}.layout{height:auto;grid-template-columns:1fr}.splitter{display:none}.pane{min-height:280px}.editor-pane{height:720px}}@media(max-width:620px){.settings-dialog{width:calc(100vw - 20px)}.settings-head,.settings-body,.settings-actions{padding-left:14px;padding-right:14px}.settings-grid{grid-template-columns:1fr}.settings-field.wide,.settings-model-row{grid-column:auto}.settings-model-row{grid-template-columns:1fr}.settings-model-row button{width:100%;margin-top:0}.settings-actions{display:grid;grid-template-columns:1fr 1fr}.settings-actions button{width:100%}.settings-actions #provider-cancel{margin-left:0}}
</style></head><body><header><h1>mdoc 手册反馈修订</h1><span id="workspace-name"></span><nav><a href="/check/?token=__TOKEN__">打开 Markdown 检查报告</a></nav></header><div id="notice" class="notice"><span></span><button title="关闭">×</button></div><section class="search"><select id="book"></select><select id="locale"></select><textarea id="query" placeholder="粘贴从 PDF 提取的精确短语；空格、换行和 Markdown 标记均严格匹配"></textarea><button id="search">严格搜索</button><button id="rebuild">重建索引</button><div id="query-meta" class="query-meta">0 字符，0 行</div></section><main class="layout"><section id="files" class="pane"><div class="empty">执行搜索后，这里按文件显示命中结果。</div></section><div class="splitter"></div><section id="matches" class="pane"><div class="empty">选择文件查看命中位置。</div></section><div class="splitter"></div><section id="workbench" class="pane editor-pane"><div class="empty">双击命中项或点击“打开修订”开始编辑。</div></section></main><dialog id="provider-dialog" class="settings-dialog"><div class="settings-head"><div><h2>AI 翻译服务设置</h2><p>配置 OpenAI 兼容接口、认证信息和默认模型</p></div><button id="provider-close" title="关闭" aria-label="关闭">×</button></div><div class="settings-body"><div id="provider-status" class="settings-status"></div><section class="settings-section"><h3>服务信息</h3><div class="settings-grid"><label class="settings-field"><span>服务名称</span><input id="provider-name" autocomplete="off"></label><label class="settings-field"><span>接口类型</span><select id="provider-type"><option value="openai-completions">OpenAI Completions</option><option value="openai-chat-completions">OpenAI Chat Completions</option></select></label><label class="settings-field wide"><span>Base URL</span><input id="provider-url" autocomplete="off" spellcheck="false"><small>填写 API 基础地址，工具会自动追加接口路径。</small></label></div></section><section class="settings-section"><h3>认证与模型</h3><div class="settings-grid"><label class="settings-field wide"><span>API Key</span><input id="provider-key" type="password" autocomplete="new-password"><small id="provider-key-hint">密钥以明文保存在本地 .mdoc/config 中，不会回传到页面。</small></label><label class="settings-field"><span>默认模型</span><input id="provider-model" list="provider-model-list" autocomplete="off"><datalist id="provider-model-list"></datalist></label><div class="settings-field"><span>模型列表</span><button id="provider-fetch" type="button">从服务读取模型</button><small id="provider-model-summary">可手动输入模型 ID。</small></div></div></section></div><div class="settings-actions"><button id="provider-delete" class="danger" type="button">删除配置</button><button id="provider-test" type="button">测试连接</button><button id="provider-cancel" type="button">取消</button><button id="provider-save" class="primary" type="button">保存配置</button></div></dialog><script>const TOKEN='__TOKEN__';</script><script src="/static/editor.js?token=__TOKEN__"></script><script src="/static/feedback-ui.js?token=__TOKEN__"></script></body></html>'''
